app.get('/media-library', requirePage(['admin', 'editor', 'author', 'media_manager']), (_req, res) => res.type('html').send(adminLayout('Media Library', `<span class="badge">Server Uploads</span><h1>Media Library</h1><div class="two"><div class="card"><input id="mtitle" placeholder="Media title"><input id="mcategory" placeholder="Category"><textarea id="mcaption" placeholder="Caption / alt text"></textarea><input type="file" id="mfile" accept="image/*"><button onclick="uploadMedia()">Upload Media</button><p id="mmsg" class="small"></p></div><div class="card manager"><h2>Assets</h2><div id="assets"></div></div></div><script>let dataUrl='';mfile.onchange=e=>{let f=e.target.files[0];let r=new FileReader();r.onload=()=>dataUrl=r.result;if(f)r.readAsDataURL(f)};async function uploadMedia(){let d=await fetch('/api/admin/media/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataUrl,title:mtitle.value,category:mcategory.value,caption:mcaption.value,alt_text:mcaption.value})}).then(r=>r.json());mmsg.className=d.success?'success':'error';mmsg.textContent=d.success?'Uploaded: '+d.url:d.message;loadAssets()}async function loadAssets(){let d=await fetch('/api/admin/media').then(r=>r.json());assets.innerHTML=(d.assets||[]).map(a=>'<div class="item"><img class="thumb" src="'+a.file_url+'"><h3>'+a.title+'</h3><p>'+a.file_url+'</p></div>').join('')||'No media yet'}loadAssets()</script>`)));
app.get('/seo-manager', requirePage(['admin', 'editor', 'author']), (_req, res) => res.type('html').send(adminLayout('SEO Manager', `<span class="badge">SEO AI</span><h1>SEO Manager</h1><div class="card"><input id="stitle" placeholder="Post/page title"><input id="scat" placeholder="Category"><button onclick="genSeo()">Generate SEO</button><pre id="seoOut" class="card"></pre></div><script>async function genSeo(){let d=await fetch('/api/ai/seo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:stitle.value,category:scat.value})}).then(r=>r.json());seoOut.textContent=JSON.stringify(d.seo,null,2)}</script>`)));
app.get('/api-test-center', requirePage(['admin', 'editor']), (_req, res) => res.type('html').send(adminLayout('API & Button Test Center', `<span class="badge">Quality Check</span><h1>API & Website Connection Test</h1><p>Run this after saving posts or homepage sections. It confirms public website and APIs read the same data.</p><button onclick="runTests()">Run Full Test</button><div id="results" class="grid"></div><pre id="raw" class="card"></pre><script>async function card(name,ok,detail){return '<div class="card '+(ok?'api-pass':'api-fail')+'"><h3>'+(ok?'✅ ':'❌ ')+name+'</h3><p>'+String(detail||'')+'</p></div>'}async function get(name,url){try{let r=await fetch(url);let d=await r.json();return {name,ok:!!d.success,detail:d.message||JSON.stringify(d.counts||{}),data:d}}catch(e){return {name,ok:false,detail:e.message}}}async function post(name,url,body){try{let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body||{})});let d=await r.json();return {name,ok:!!d.success,detail:d.source||d.message||'OK',data:d}}catch(e){return {name,ok:false,detail:e.message}}}async function runTests(){results.innerHTML='Running...';let tests=[];tests.push(await get('Health API','/api/health'));tests.push(await get('Session API','/api/auth/me'));tests.push(await get('Categories API','/api/categories'));tests.push(await get('Posts API','/api/posts'));tests.push(await get('Homepage API','/api/homepage'));tests.push(await get('Publish Connection','/api/admin/publish-check'));tests.push(await get('Media API','/api/admin/media'));tests.push(await get('AI Status API','/api/ai/status'));tests.push(await post('SEO AI Button/API','/api/ai/seo',{title:'Test SEO',category:'Viral India'}));tests.push(await post('Post AI Button/API','/api/ai/post-assist',{title:'',category:'Viral India',idea:'test jaipur india story'}));tests.push(await get('System Check','/api/admin/system-check'));results.innerHTML=(await Promise.all(tests.map(t=>card(t.name,t.ok,t.detail)))).join('');raw.textContent=JSON.stringify(tests,null,2)}</script>`)));
app.get('/users', requirePage(['admin']), (_req, res) => res.type('html').send(adminLayout('Users & Roles', `<span class="badge">Roles</span><h1>Users & Roles</h1><div class="grid">${ROLES.map(r => `<div class="card"><h3>${r}</h3><p>Role-based CMS access enabled.</p></div>`).join('')}</div>`)));

function studioScript() { return `const qs=x=>document.getElementById(x);let allPosts=[],cover='';function safe(v){return String(v||'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]))}function localGen(){let c=category.value,t=title.value||((idea.value||c+' Story').split(/[.?!\\n]/)[0].slice(0,72)+': A Vivid India Story'),i=idea.value||content.value||t;return{title:t,category:c,excerpt:t+' connects audience interest with India’s culture and global identity.',content:t+'\\n\\n'+i+' is a strong magazine story because it explains the topic with context, colour and human emotion.\\n\\nIndia is vivid because local moments carry national memory. This story connects people, place, culture and modern attention in a simple global style.\\n\\nहिंदी भाव: यह कहानी भारत की संस्कृति, रंग और पहचान को सरल भाषा में सामने लाती है।',hashtags:['#India','#VividIndia','#IndianCulture','#AIMagazine']}}function fill(x,source){x=x||localGen();title.value=x.title||title.value;category.value=x.category||category.value;excerpt.value=x.excerpt||'';content.value=x.content||'';hashtags.value=Array.isArray(x.hashtags)?x.hashtags.join(' '):(x.hashtags||hashtags.value);msg.className='success';msg.textContent='Generated using '+source+'. Review and save.'}async function postAi(mode){msg.className='small';msg.textContent='Generating...';try{let d=await fetch('/api/ai/post-assist',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,category:category.value,title:title.value,idea:idea.value,content:content.value||idea.value,language:language.value})}).then(r=>r.json());fill(d.suggestion||localGen(),d.source||'api')}catch(e){fill(localGen(),'browser-fallback')}}async function seoAi(){let d=await fetch('/api/ai/seo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:title.value||idea.value,category:category.value})}).then(r=>r.json());msg.className='success';msg.textContent='SEO: '+d.seo.meta_title+' | '+d.seo.keywords.join(', ')}async function aiStatus(){let d=await fetch('/api/ai/status').then(r=>r.json());msg.className=d.openaiConfigured?'success':'error';msg.textContent=d.openaiConfigured?'OpenAI configured: '+d.model:'OpenAI key missing. Fallback will still generate content.'}async function loadPosts(){postList.innerHTML='Loading...';let d=await fetch('/api/admin/posts').then(r=>r.json());allPosts=d.posts||[];postList.innerHTML=allPosts.map(p=>'<div class="item"><h3>'+safe(p.title)+'</h3><p class="small">'+safe(p.category)+'</p><button onclick="editPost('+p.id+')">Edit</button><button class="danger" onclick="deletePost('+p.id+')">Delete</button></div>').join('')||'No posts yet'}function newPost(){postId.value='';title.value='';idea.value='';excerpt.value='';content.value='';hashtags.value='';cover_image.value='';cover=''}function editPost(id){let p=allPosts.find(x=>Number(x.id)===Number(id));if(!p)return;postId.value=p.id;category.value=p.category||'Viral India';language.value=p.language||'en';title.value=p.title||'';excerpt.value=p.excerpt||'';content.value=(p.content||'').replace(/\\n\\n#.*$/s,'');hashtags.value=((p.content||'').match(/#\\w+/g)||[]).join(' ');cover_image.value=p.cover_image||''}async function savePost(){let id=postId.value;let body={title:title.value,category:category.value,language:language.value,excerpt:excerpt.value,content:content.value,hashtags:hashtags.value,cover_image:cover_image.value};let d=await fetch(id?'/api/posts/'+id:'/api/posts',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json());msg.className='success';msg.textContent='Saved using '+d.source+'. Check /posts.';await loadPosts()}async function deleteCurrent(){if(postId.value)await deletePost(postId.value)}async function deletePost(id){if(!confirm('Delete post?'))return;await fetch('/api/posts/'+id,{method:'DELETE'});await loadPosts()}async function seedBlogs(){let d=await fetch('/api/admin/seed-category-blogs',{method:'POST'}).then(r=>r.json());msg.className='success';msg.textContent='Created '+d.created+' category blogs';await loadPosts()}function apply(){preview.style.setProperty('--b',b.value);preview.style.setProperty('--c',c.value);preview.style.setProperty('--s',s.value);preview.style.setProperty('--sep',sep.value)}['b','c','s','sep'].forEach(id=>qs(id).oninput=apply);photo.onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{cover=r.result;preview.src=cover;apply()};r.readAsDataURL(f)};function mediaPreset(n){let v=n==='heritage'?[1.08,1.15,1.2,.25]:[1.15,1.25,1.6,.05];b.value=v[0];c.value=v[1];s.value=v[2];sep.value=v[3];apply();msg.className='success';msg.textContent='Studio AI media preset applied.'}async function uploadCover(){if(!cover)return alert('Choose image first');let d=await fetch('/api/admin/media/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataUrl:cover,title:title.value||'cover',category:category.value,caption:excerpt.value})}).then(r=>r.json());if(d.success){cover_image.value=d.url;msg.className='success';msg.textContent='Cover uploaded: '+d.url}else{msg.className='error';msg.textContent=d.message}}async function mediaIdea(){let d=await fetch('/api/ai/media-suggest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({category:category.value,title:title.value})}).then(r=>r.json());msg.className='success';msg.textContent=d.suggestion.prompt}loadPosts();`; }
function builderScript() { return `let section='heroBanners',items=[],media='';function safe(v){return String(v||'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]))}function openTab(s){section=s;newItem();load()}file.onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{media=r.result;imagePreview.src=media};r.readAsDataURL(f)}async function uploadBuilderMedia(){if(media&&media.startsWith('data:')){bmsg.className='small';bmsg.textContent='Uploading image to server...';let d=await fetch('/api/admin/media/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataUrl:media,title:title.value||section,category:section,caption:description.value})}).then(r=>r.json());if(!d.success)throw new Error(d.message||'Upload failed');media=d.url;imagePreview.src=media;}return media;}async function load(){let d=await fetch('/api/admin/homepage/'+section).then(r=>r.json());items=d.items||[];listTitle.textContent={heroBanners:'Hero Banner',subHeroBanners:'Sub Hero',mediaGallery:'Media Gallery',tiles:'Tiles Block'}[section];builderList.innerHTML=items.map(x=>'<div class="item"><h3>'+safe(x.title)+'</h3>'+((x.image_url||x.file_url)?'<img class="thumb" src="'+(x.image_url||x.file_url)+'">':'')+'<p class="small">Order '+(x.sort_order||0)+'</p><button onclick="edit('+x.id+')">Edit</button></div>').join('')||'<p>No items yet.</p>'}function newItem(){itemId.value='';title.value='';subtitle.value='';description.value='';btn1.value='';link1.value='';icon.value='';bg.value='';sort.value='0';active.value='1';media='';imagePreview.src=''}function edit(id){let x=items.find(i=>Number(i.id)===Number(id));if(!x)return;itemId.value=x.id;title.value=x.title||'';subtitle.value=x.subtitle||x.short_text||x.category||'';description.value=x.description||x.caption||'';btn1.value=x.button1_text||x.button_text||'';link1.value=x.button1_link||x.button_link||'';icon.value=x.icon_name||'';bg.value=x.bg_color||'';sort.value=x.sort_order||0;active.value=Number(x.is_active)!==0?'1':'0';media=x.image_url||x.file_url||'';imagePreview.src=media}function payload(){let p={title:title.value,sort_order:Number(sort.value||0),is_active:Number(active.value)};if(section==='heroBanners')Object.assign(p,{subtitle:subtitle.value,description:description.value,button1_text:btn1.value,button1_link:link1.value,button2_text:'Open CMS',button2_link:'/dashboard',image_url:media});else if(section==='subHeroBanners')Object.assign(p,{short_text:subtitle.value,image_url:media,button_text:btn1.value,button_link:link1.value});else if(section==='mediaGallery')Object.assign(p,{media_type:'image',caption:description.value,file_url:media,category:subtitle.value,is_featured:1});else Object.assign(p,{description:description.value,image_url:media,icon_name:icon.value,bg_color:bg.value||'#fff7ed',button_text:btn1.value,button_link:link1.value,tile_size:'medium'});return p}async function saveItem(){try{await uploadBuilderMedia();let id=itemId.value;let d=await fetch(id?'/api/admin/homepage/'+section+'/'+id:'/api/admin/homepage/'+section,{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload())}).then(r=>r.json());bmsg.className=d.success?'success':'error';bmsg.textContent=d.success?'Saved using '+d.source+'. Open homepage preview.':d.message;await load()}catch(e){bmsg.className='error';bmsg.textContent=e.message}}async function deleteItem(){if(!itemId.value)return alert('Select item first');await fetch('/api/admin/homepage/'+section+'/'+itemId.value,{method:'DELETE'});newItem();await load()}load();`; }

